/bin/bash -lc "python - <<'PY'
import json,re
x=json.load(open('judge-input.json'))
o=next(o for o in x['outputs'] if o['caseId']=='agent_access')
for n in o['numberedLines'][:27]: print(str(n['line'])+': '+n['text'])
for o in x['outputs']:
 print('\\n'+o['caseId'])
 for n in o['numberedLines']:
  if re.match(r'"'^[|`]-- '"',n['text']): print(str(n['line'])+': '+n['text'])
PY"

